const questions = ["How is my health?", "Did we ever manage to buy a house?", "What should I change?"];
const results = [];
for (const q of questions) {
  const tts = await speak(q);
  const pcm = floatToPcm16(resample(tts.samples, 1.5));       // what the headset mic would send: 16 kHz
  const trailing = Buffer.alloc(16000 * 2 * 3);                // a few seconds of silence after speaking
  const all = Buffer.concat([pcm, trailing]);
  const r = await new Promise((resolve) => {
    const ws = new WebSocket("ws://127.0.0.1:3001/voice");
    const got = []; let endOfSpeechAt = 0; let firstAudioAt = 0; let transcriptAt = 0;
    ws.onopen = async () => {
      for (let i = 0; i < all.length; i += 3200) {
        ws.send(JSON.stringify({ type: "audio", data: all.subarray(i, i + 3200).toString("base64"), sampleRate: 16000 }));
        if (!endOfSpeechAt && i + 3200 >= pcm.length) endOfSpeechAt = performance.now();
        await new Promise((r) => setTimeout(r, 100));
        if (firstAudioAt) break;
      }
    };
    ws.onmessage = (e) => {
      const m = JSON.parse(e.data); got.push(m);
      if (m.type === "transcript") transcriptAt = performance.now();
      if (m.type === "reply" && m.audio && !firstAudioAt) firstAudioAt = performance.now();
      if (m.type === "reply" && m.done) { setTimeout(() => { ws.close(); resolve({ got, endOfSpeechAt, transcriptAt, firstAudioAt }); }, 200); }
    };
    setTimeout(() => { ws.close(); resolve({ got, endOfSpeechAt, transcriptAt, firstAudioAt, timeout: true }); }, 20000);
  });
  const heard = r.got.find((m) => m.type === "transcript")?.text;
  const first = r.got.find((m) => m.type === "reply");
  console.log(`Q: "${q}"`);
  console.log(`   heard:  "${heard}"`);
  console.log(`   reply:  "${first?.sentence}"${r.timeout ? "  (TIMED OUT)" : ""}`);
  if (r.firstAudioAt) console.log(`   end of speech -> text: ${Math.round(r.transcriptAt - r.endOfSpeechAt)} ms | -> first audio: ${Math.round(r.firstAudioAt - r.endOfSpeechAt)} ms`);
  const errs = r.got.filter((m) => m.type === "error"); if (errs.length) console.log("   errors:", JSON.stringify(errs));
  if (r.firstAudioAt) results.push(r.firstAudioAt - r.endOfSpeechAt);
}
results.sort((a, b) => a - b);
console.log("first-audio delays (ms):", results.map(Math.round).join(", "));
EOF
